<label><input id="regionViewInput" type="checkbox" onchange="toggle_regionView(this.checked)"> View: highlight cut construction</label>
<label>Hole size: <output id="holeSizeVal">100</output><input id="holeSizeInput" type="range" min="70" max="130" step="1" value="100" oninput="document.getElementById('holeSizeVal').value=this.value;update_holeSize(+this.value)"></label>
