<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 600, 1000);

var blue = '#2a9fda';
var fillBlue = '#c7e4f1';
var ink = '#222222';
var cutHi = '#e18b19';
var hole = { x: 360, y: 255, s: 1 };
var defaultHole = { x: 360, y: 255, s: 1 };
var currentStep = 0;
var cutHighlight = false;
var cancelMode = false;
var root = draw.group();

var demoSteps = [
  {
    title: 'Positive boundary orientation',
    narration: 'The region has one hole, so its boundary has two components. The outer boundary C1 is oriented counterclockwise, while the inner boundary C2 is oriented clockwise so that the region always stays on the left as the boundary is traversed.',
    state: { regionView: 'Multiply connected region' }
  },
  {
    title: 'Introduce the cuts',
    narration: 'Switch to the cut view: two horizontal cuts connect the hole to the outer boundary, dividing the region into simply connected pieces R′ and R″. These pieces are now suitable for applying Green’s Theorem separately.',
    state: { regionView: 'Cut into simply connected regions' }
  },
  {
    title: 'See the cancellation',
    narration: 'Along each artificial cut, one sub-region traverses the cut in one direction while the neighboring sub-region traverses it in the opposite direction. When the boundary integrals are added, those cut contributions cancel, leaving only C1 and C2.',
    state: { regionView: 'Cut into simply connected regions' }
  }
];

function outerPath(y0) {
  return [
    'M', 175, 55 + y0,
    'C', 240, 20 + y0, 330, 48 + y0, 398, 115 + y0,
    'C', 495, 210 + y0, 525, 356 + y0, 424, 430 + y0,
    'C', 350, 484 + y0, 210, 465 + y0, 142, 407 + y0,
    'C', 75, 349 + y0, 103, 281 + y0, 138, 239 + y0,
    'C', 166, 207 + y0, 152, 174 + y0, 101, 177 + y0,
    'C', 45, 180 + y0, 30, 166 + y0, 31, 128 + y0,
    'C', 32, 89 + y0, 75, 60 + y0, 175, 55 + y0,
    'Z'
  ].join(' ');
}

function innerPath(y0) {
  var cx = hole.x, cy = hole.y + y0, s = hole.s;
  function px(dx) { return cx + dx * s; }
  function py(dy) { return cy + dy * s; }
  return [
    'M', px(-58), py(-45),
    'C', px(-28), py(-66), px(46), py(-52), px(68), py(8),
    'C', px(91), py(70), px(37), py(124), px(-32), py(111),
    'C', px(-78), py(104), px(-83), py(58), px(-65), py(28),
    'C', px(-111), py(25), px(-100), py(-31), px(-58), py(-45),
    'Z'
  ].join(' ');
}

function combinedPath(y0) {
  return outerPath(y0) + ' ' + innerPath(y0);
}

function label(g, txt, x, y, size) {
  return g.text(txt)
    .font({ family: 'Times New Roman, Times, serif', size: size, style: 'italic', anchor: 'middle' })
    .fill(ink)
    .center(x, y)
    .attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
}

function arrowAt(g, x, y, angleDeg, size, color, opacity) {
  var a = angleDeg * Math.PI / 180;
  var tip = [x, y];
  var back = [x - Math.cos(a) * size, y - Math.sin(a) * size];
  var n = [-Math.sin(a), Math.cos(a)];
  var w = size * 0.48;
  return g.polygon([
    tip[0], tip[1],
    back[0] + n[0] * w, back[1] + n[1] * w,
    back[0] - n[0] * w, back[1] - n[1] * w
  ]).fill({ color: color, opacity: opacity == null ? 1 : opacity }).stroke('none');
}

function lineArrow(g, x, y, angleDeg, color, opacity) {
  arrowAt(g, x, y, angleDeg, 24, color, opacity);
}

function makeInteractive(el, tip, title, body) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup(title, body); });
}

function cutGeom() {
  var s = hole.s;
  var yTop = hole.y + 6 * s;
  var yBot = hole.y + 42 * s;
  var innerLTop = hole.x - 86 * s;
  var innerRTop = hole.x + 84 * s;
  var innerLBot = hole.x - 74 * s;
  var innerRBot = hole.x + 76 * s;
  var leftOuter = Math.max(72, Math.min(innerLTop - 130, 180));
  var rightOuter = Math.min(535, Math.max(innerRTop + 110, 445));
  return {
    yTop: yTop, yBot: yBot,
    innerLTop: innerLTop, innerRTop: innerRTop,
    innerLBot: innerLBot, innerRBot: innerRBot,
    leftOuter: leftOuter, rightOuter: rightOuter
  };
}

function drawCuts(g, y0) {
  var c = cutGeom();
  var cg = g.group();
  var parts = [
    [c.leftOuter, c.yTop + y0, c.innerLTop, c.yTop + y0],
    [c.innerRTop, c.yTop + y0, c.rightOuter, c.yTop + y0],
    [c.leftOuter, c.yBot + y0, c.innerLBot, c.yBot + y0],
    [c.innerRBot, c.yBot + y0, c.rightOuter, c.yBot + y0]
  ];
  for (var i = 0; i < parts.length; i++) {
    cg.line(parts[i][0], parts[i][1], parts[i][2], parts[i][3]).stroke({ color: ink, width: 4, linecap: 'butt' });
  }
  lineArrow(cg, (c.leftOuter + c.innerLTop) / 2 + 18, c.yTop + y0, 0, ink, 1);
  lineArrow(cg, (c.innerRTop + c.rightOuter) / 2 + 28, c.yTop + y0, 0, ink, 1);
  lineArrow(cg, (c.leftOuter + c.innerLBot) / 2 - 18, c.yBot + y0, 180, ink, 1);
  lineArrow(cg, (c.innerRBot + c.rightOuter) / 2 - 28, c.yBot + y0, 180, ink, 1);

  if (cutHighlight) {
    var hg = g.group().opacity(cancelMode ? 0.92 : 0.72);
    for (var j = 0; j < parts.length; j++) {
      hg.line(parts[j][0], parts[j][1], parts[j][2], parts[j][3])
        .stroke({ color: cutHi, width: cancelMode ? 7 : 5, linecap: 'round' });
    }
    lineArrow(hg, (c.leftOuter + c.innerLTop) / 2 + 18, c.yTop + y0 - 1, 0, cutHi, 1);
    lineArrow(hg, (c.innerRTop + c.rightOuter) / 2 + 28, c.yTop + y0 - 1, 0, cutHi, 1);
    lineArrow(hg, (c.leftOuter + c.innerLBot) / 2 - 18, c.yBot + y0 + 1, 180, cutHi, 1);
    lineArrow(hg, (c.innerRBot + c.rightOuter) / 2 - 28, c.yBot + y0 + 1, 180, cutHi, 1);
    makeInteractive(hg, 'Opposite arrows on the same artificial cut cancel in the sum.', 'Cut cancellation', 'Each cut appears twice: once on the boundary of the upper piece and once on the boundary of the lower piece. The two traversals have opposite directions, so their line integrals cancel.');
  }

  makeInteractive(cg, 'Artificial cut boundaries are temporary.', 'Artificial cuts', 'The cuts make the pieces simply connected so Green’s Theorem can be applied separately. They are not part of the final boundary because opposite orientations cancel.');
}

function drawPanel(y0, cutPanel) {
  var g = root.group();

  var region = g.path(combinedPath(y0))
    .fill(fillBlue)
    .attr({ 'fill-rule': 'evenodd' })
    .stroke('none');
  makeInteractive(region, cutPanel ? 'Cut version of the region.' : 'Multiply connected region R.', cutPanel ? 'Cut region' : 'Region R', cutPanel ? 'The same hole remains, but two cuts split the region into simply connected pieces.' : 'A hole makes the region multiply connected. The positive boundary orientation uses counterclockwise motion on the outside and clockwise motion around the hole.');

  if (cutPanel) drawCuts(g, y0);

  var outer = g.path(outerPath(y0)).fill('none').stroke({ color: blue, width: 8, linecap: 'round', linejoin: 'round' });
  var inner = g.path(innerPath(y0)).fill('#ffffff').stroke({ color: blue, width: 8, linecap: 'round', linejoin: 'round' });

  makeInteractive(outer, 'C1 is counterclockwise.', 'Outer boundary C1', 'For positive orientation, the outer boundary is traversed counterclockwise. As you move along C1, the region lies on your left.');
  makeInteractive(inner, 'Drag the hole. C2 stays clockwise.', 'Inner boundary C2', 'The inner boundary is oriented clockwise. This keeps the shaded region, rather than the hole, on the left side of the traversal.');

  arrowAt(g, 150, 63 + y0, 168, 43, blue);
  arrowAt(g, 425, 416 + y0, -42, 43, blue);
  arrowAt(g, hole.x + 73 * hole.s, hole.y - 15 * hole.s + y0, 45, 38, blue);
  arrowAt(g, hole.x - 45 * hole.s, hole.y + 80 * hole.s + y0, -102, 38, blue);

  if (!cutPanel) {
    label(g, 'R', 285, 188 + y0, 56);
    label(g, 'C₁', 315, 23 + y0, 50);
    label(g, 'C₂', hole.x + 8, hole.y - 58 * hole.s + y0, 46);
    label(g, '(a)', 300, 476 + y0, 48);
  } else {
    label(g, 'R′', 282, 170 + y0, 52);
    label(g, 'C₁', 315, 25 + y0, 50);
    label(g, 'C₂', hole.x - 15, hole.y - 52 * hole.s + y0, 46);
    label(g, 'R″', 270, 357 + y0, 52);
    label(g, '(b)', 300, 490 + y0, 48);
  }

  enableHoleDrag(inner, y0);
}

function enableHoleDrag(el, panelY) {
  el.on('mousedown', function (e) {
    e.preventDefault();
    var p = svgPoint(e);
    dragState = {
      panelY: panelY,
      dx: p.x - hole.x,
      dy: p.y - panelY - hole.y,
      moved: false
    };
  });
}

function svgPoint(evt) {
  var pt = draw.node.createSVGPoint();
  pt.x = evt.clientX;
  pt.y = evt.clientY;
  return pt.matrixTransform(draw.node.getScreenCTM().inverse());
}

function constrainHole() {
  hole.x = Math.max(270, Math.min(408, hole.x));
  hole.y = Math.max(190, Math.min(310, hole.y));
  hole.s = Math.max(0.7, Math.min(1.3, hole.s));
}

function render() {
  root.clear();
  drawPanel(0, false);
  drawPanel(480, true);
}

var dragState = null;
window.addEventListener('mousemove', function (e) {
  if (!dragState) return;
  var p = svgPoint(e);
  hole.x = p.x - dragState.dx;
  hole.y = p.y - dragState.panelY - dragState.dy;
  dragState.moved = true;
  constrainHole();
  render();
});
window.addEventListener('mouseup', function () {
  dragState = null;
});

function update_holeSize(v) {
  hole.s = v / 100;
  constrainHole();
  render();
}

function trigger_resetHole() {
  hole.x = defaultHole.x;
  hole.y = defaultHole.y;
  hole.s = defaultHole.s;
  document.getElementById('holeSizeInput').value = 100;
  document.getElementById('holeSizeVal').value = 100;
  render();
}

function toggle_regionView(on) {
  cutHighlight = !!on;
  cancelMode = currentStep === 2 && !!on;
  render();
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + ' / ' + demoSteps.length;
  var on = step.state.regionView === 'Cut into simply connected regions';
  document.getElementById('regionViewInput').checked = on;
  cutHighlight = on;
  cancelMode = currentStep === 2;
  render();
}

function nextStep() {
  applyStep((currentStep + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((currentStep + demoSteps.length - 1) % demoSteps.length);
}

render();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

