  return g.polygon([
    tip[0], tip[1],
    back[0] + n[0] * w, back[1] + n[1] * w,
    back[0] - n[0] * w, back[1] - n[1] * w
  ]).fill({ color: color, opacity: opacity == null ? 1 : opacity }).stroke('none');
}

function makeInteractive(el, tip, title, body) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup(title, body); });
}

function cutGeom() {
  var s = hole.s;
  var yTop = hole.y + 12 * s;
  var yBot = hole.y + 70 * s;
  var innerLTop = hole.x - 74 * s;
  var innerRTop = hole.x + 72 * s;
  var innerLBot = hole.x - 62 * s;
  var innerRBot = hole.x + 74 * s;
  return {
    yTop: yTop,
    yBot: yBot,
    innerLTop: innerLTop,
    innerRTop: innerRTop,
    innerLBot: innerLBot,
    innerRBot: innerRBot,
    leftOuterTop: Math.max(120, Math.min(188, innerLTop - 92)),
    leftOuterBot: Math.max(108, Math.min(170, innerLBot - 112)),
    rightOuterTop: Math.min(466, Math.max(412, innerRTop + 62)),
    rightOuterBot: Math.min(462, Math.max(414, innerRBot + 58))
  };
}

function smallLineArrow(g, x, y, angleDeg, color, opacity) {
  arrowAt(g, x, y, angleDeg, 22, color, opacity);
}

function drawCuts(g, y0) {
  var c = cutGeom();
  var cg = g.group();
  var parts = [
    [c.leftOuterTop, c.yTop + y0, c.innerLTop, c.yTop + y0],
    [c.innerRTop, c.yTop + y0, c.rightOuterTop, c.yTop + y0],
    [c.leftOuterBot, c.yBot + y0, c.innerLBot, c.yBot + y0],
    [c.innerRBot, c.yBot + y0, c.rightOuterBot, c.yBot + y0]
  ];

  for (var i = 0; i < parts.length; i++) {
    cg.line(parts[i][0], parts[i][1], parts[i][2], parts[i][3])
      .stroke({ color: ink, width: 4, linecap: 'butt' });
  }

  smallLineArrow(cg, (c.leftOuterTop + c.innerLTop) / 2 + 20, c.yTop + y0, 0, ink, 1);
  smallLineArrow(cg, (c.innerRTop + c.rightOuterTop) / 2 + 22, c.yTop + y0, 0, ink, 1);
  smallLineArrow(cg, (c.leftOuterBot + c.innerLBot) / 2 - 18, c.yBot + y0, 180, ink, 1);
  smallLineArrow(cg, (c.innerRBot + c.rightOuterBot) / 2 - 20, c.yBot + y0, 180, ink, 1);

  makeInteractive(cg, 'Artificial cut boundaries are temporary.', 'Artificial cuts', 'The cuts make the pieces simply connected so Green’s Theorem can be applied separately. They are not part of the final boundary because opposite orientations cancel.');

  if (cutHighlight) {
    var hg = g.group().opacity(cancelMode ? 0.94 : 0.72);
    for (var j = 0; j < parts.length; j++) {
      hg.line(parts[j][0], parts[j][1], parts[j][2], parts[j][3])
        .stroke({ color: cutHi, width: cancelMode ? 7 : 5, linecap: 'round' });
    }
    smallLineArrow(hg, (c.leftOuterTop + c.innerLTop) / 2 + 20, c.yTop + y0 - 1, 0, cutHi, 1);
    smallLineArrow(hg, (c.innerRTop + c.rightOuterTop) / 2 + 22, c.yTop + y0 - 1, 0, cutHi, 1);
    smallLineArrow(hg, (c.leftOuterBot + c.innerLBot) / 2 - 18, c.yBot + y0 + 1, 180, cutHi, 1);
    smallLineArrow(hg, (c.innerRBot + c.rightOuterBot) / 2 - 20, c.yBot + y0 + 1, 180, cutHi, 1);
    makeInteractive(hg, 'Opposite arrows on the same artificial cut cancel in the sum.', 'Cut cancellation', 'Each cut appears twice: once on the boundary of the upper piece and once on the boundary of the lower piece. The two traversals have opposite directions, so their line integrals cancel.');
  }
}

function drawPanel(y0, cutPanel) {
  var g = root.group();

  var region = g.path(combinedPath(y0))
    .fill(fillBlue)
    .attr({ 'fill-rule': 'evenodd' })
    .stroke('none');
  makeInteractive(region, cutPanel ? 'Cut version of the same region.' : 'Multiply connected region R.', cutPanel ? 'Cut region' : 'Region R', cutPanel ? 'The same hole remains, but two cuts split the region into simply connected pieces.' : 'A hole makes the region multiply connected. The positive boundary orientation uses counterclockwise motion on the outside and clockwise motion around the hole.');

  if (cutPanel) drawCuts(g, y0);

  var outer = g.path(outerPath(y0))
    .fill('none')
    .stroke({ color: blue, width: 8, linecap: 'round', linejoin: 'round' });
  var inner = g.path(innerPath(y0))
    .fill('#ffffff')
    .stroke({ color: blue, width: 8, linecap: 'round', linejoin: 'round' });

  makeInteractive(outer, 'C1 is counterclockwise.', 'Outer boundary C1', 'For positive orientation, the outer boundary is traversed counterclockwise. As you move along C1, the region lies on your left.');
  makeInteractive(inner, 'Drag the hole. C2 stays clockwise.', 'Inner boundary C2', 'The inner boundary is oriented clockwise. This keeps the shaded region, rather than the hole, on the left side of the traversal.');

  arrowAt(g, 128, 88 + y0, 166, 44, blue);
  arrowAt(g, 397, 518 + y0, 14, 44, blue);
  arrowAt(g, hole.x + 69 * hole.s, hole.y - 20 * hole.s + y0, 49, 39, blue);
  arrowAt(g, hole.x - 47 * hole.s, hole.y + 92 * hole.s + y0, -78, 39, blue);

  if (!cutPanel) {
    label(g, 'R', 230, 205 + y0, 56);
    label(g, 'C₁', 260, 28 + y0, 50);
    label(g, 'C₂', hole.x + 8, hole.y - 104 * hole.s + y0, 46);
    label(g, '(a)', 260, 632 + y0, 52);
  } else {
    label(g, 'R′', 226, 197 + y0, 52);
    label(g, 'C₁', 260, 34 + y0, 50);
    label(g, 'C₂', hole.x - 6, hole.y - 102 * hole.s + y0, 46);
    label(g, 'R″', 218, 456 + y0, 52);
    label(g, '(b)', 260, 618 + y0, 52);
  }

  enableHoleDrag(inner, y0);
}

function enableHoleDrag(el, panelY) {
  el.on('mousedown', function (e) {
    e.preventDefault();
    var p = svgPoint(e);
    dragState = {
      panelY: panelY,
      dx: p.x - hole.x,
      dy: p.y - panelY - hole.y
    };
  });
}

function svgPoint(evt) {
  var pt = draw.node.createSVGPoint();
  pt.x = evt.clientX;
  pt.y = evt.clientY;
  return pt.matrixTransform(draw.node.getScreenCTM().inverse());
}

function constrainHole() {
  hole.x = Math.max(294, Math.min(358, hole.x));
  hole.y = Math.max(290, Math.min(356, hole.y));
  hole.s = Math.max(0.75, Math.min(1.25, hole.s));
}

function render() {
  root.clear();
  drawPanel(24, false);
  drawPanel(704, true);
}

window.addEventListener('mousemove', function (e) {
  if (!dragState) return;
  var p = svgPoint(e);
  hole.x = p.x - dragState.dx;
  hole.y = p.y - dragState.panelY - dragState.dy;
  constrainHole();
  render();
});

window.addEventListener('mouseup', function () {
  dragState = null;
});

function update_holeSize(v) {
  hole.s = v / 100;
  constrainHole();
  render();
}

function trigger_resetHole() {
  hole.x = defaultHole.x;
  hole.y = defaultHole.y;
  hole.s = defaultHole.s;
  document.getElementById('holeSizeInput').value = 100;
  document.getElementById('holeSizeVal').value = 100;
  render();
}

function toggle_regionView(on) {
  cutHighlight = !!on;
  cancelMode = currentStep === 2 && !!on;
  render();
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + ' / ' + demoSteps.length;

  var on = step.state.regionView === 'Cut into simply connected regions';
  document.getElementById('regionViewInput').checked = on;
  cutHighlight = on;
  cancelMode = currentStep === 2 && on;
  render();
}

function nextStep() {
  applyStep((currentStep + 1) % demoSteps.length);
}

function prevStep() {
  applyStep((currentStep + demoSteps.length - 1) % demoSteps.length);
}

render();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

